-- Станции метро, МЦК и МЦД Москвы. Одна строка на станцию на линии: у пересадочных
-- узлов несколько строк с разными id. Данные: https://api.hh.ru/metro/1
-- В hh.ru «ё» проставлена не везде; в названиях она восстановлена вручную.
CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE IF NOT EXISTS metro_stations (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    line_id        TEXT NOT NULL,
    line_name      TEXT NOT NULL,
    line_color     TEXT NOT NULL,
    transport_type TEXT NOT NULL CHECK (transport_type IN ('metro', 'mcc', 'mcd')),
    location       geometry(Point, 4326) NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_metro_stations_location
    ON metro_stations USING GIST (location);

ON CONFLICT (id) DO UPDATE SET
    name           = EXCLUDED.name,
    line_id        = EXCLUDED.line_id,
    line_name      = EXCLUDED.line_name,
    line_color     = EXCLUDED.line_color,
    transport_type = EXCLUDED.transport_type,
    location       = EXCLUDED.location;

-- Ближайшая станция и расстояние по прямой в метрах (по сфероиду WGS 84).
-- В градусах 4326 долгота на широте Москвы «сжата», поэтому KNN по индексу даёт
-- кандидатов, а победитель выбирается по geography-расстоянию. Кандидатов с запасом:
-- пересадочные узлы (Нижегородская и т.п.) дают до ~6 строк в одной точке.
CREATE OR REPLACE VIEW apartment_nearest_metro AS
SELECT
    a.source,
    a.external_id,
    m.id             AS station_id,
    m.name           AS station_name,
    m.line_name,
    m.transport_type,
    m.distance_m
FROM apartments a
CROSS JOIN LATERAL (
    SELECT c.id, c.name, c.line_name, c.transport_type,
           round(ST_Distance(a.location::geography, c.location::geography))::int AS distance_m
    FROM (
        SELECT ms.*
        FROM metro_stations ms
        ORDER BY ms.location <-> a.location
        LIMIT 50
    ) c
    ORDER BY distance_m
    LIMIT 1
) m
WHERE a.location IS NOT NULL;
